alter table tasks enable row level security;
alter table tasks force row level security;
drop policy if exists tasks_tenant_read on tasks;
create policy tasks_tenant_read on tasks for select using (app.member_ok() AND (tenant_id = app.tenant_id() AND scope_id = ANY(visible_scopes(app.user_id()))));
drop policy if exists tasks_permission_write_insert on tasks;
create policy tasks_permission_write_insert on tasks for insert with check (app.member_ok() AND (tenant_id = app.tenant_id() AND has_permission(app.user_id(), 'tasks', scope_id, 'edit')));
drop policy if exists tasks_permission_write_update on tasks;
create policy tasks_permission_write_update on tasks for update using (app.member_ok() AND (tenant_id = app.tenant_id() AND has_permission(app.user_id(), 'tasks', scope_id, 'edit'))) with check (app.member_ok() AND (tenant_id = app.tenant_id() AND has_permission(app.user_id(), 'tasks', scope_id, 'edit')));
drop policy if exists tasks_permission_write_delete on tasks;
create policy tasks_permission_write_delete on tasks for delete using (app.member_ok() AND (tenant_id = app.tenant_id() AND has_permission(app.user_id(), 'tasks', scope_id, 'edit')));
drop policy if exists tasks_ops_read_with_grant on tasks;
create policy tasks_ops_read_with_grant on tasks for select using (app.ops_grant_ok(tasks.tenant_id));

