alter table credential_kinds force row level security;
drop policy if exists credential_kinds_all_read on credential_kinds;
create policy credential_kinds_all_read on credential_kinds for select using (coalesce(current_setting('app.user_id', true), '') <> '' AND (true));
drop policy if exists credential_kinds_ops_write_insert on credential_kinds;
create policy credential_kinds_ops_write_insert on credential_kinds for insert with check (current_setting('app.role', true) = 'ops');
drop policy if exists credential_kinds_ops_write_update on credential_kinds;
create policy credential_kinds_ops_write_update on credential_kinds for update using (current_setting('app.role', true) = 'ops') with check (current_setting('app.role', true) = 'ops');
drop policy if exists credential_kinds_ops_write_delete on credential_kinds;
create policy credential_kinds_ops_write_delete on credential_kinds for delete using (current_setting('app.role', true) = 'ops');

